#![allow(dead_code)]
use std::io::{BufRead,BufReader};
use std::sync::atomic::Ordering;
use serde_json::{Value,json};
use openvector::image_document::{DocumentSnapshot,DocumentProgress,CANCEL_TASK};
use crate::editor_support::{compare_json,compare_settings,hex};
fn rows(name:&str)->impl Iterator<Item=Value>{let file=std::fs::File::open(crate::common::fixture_path(name)).unwrap();BufReader::new(flate2::read::MultiGzDecoder::new(file)).lines().map(|line|serde_json::from_str(&line.unwrap()).unwrap())}
fn registry()->Value{rows("document-vector-stages-reference.ndjson.gz").next().unwrap()["parameters"].clone()}
fn bits(values:&[f32])->Vec<u8>{values.iter().flat_map(|v|v.to_le_bytes()).collect()}
pub fn compare_vector_document(state:&DocumentSnapshot,native:&Value,registry:&Value,label:&str,returned:bool,fitting_complete:bool){
    if returned{assert_eq!(state.status as u64,native["status"].as_u64().unwrap(),"{label} status");}
    assert_eq!(state.progress as i64,native["progress"].as_i64().unwrap(),"{label} progress");assert_eq!(state.cancelled,native["cancelled"].as_bool().unwrap(),"{label} cancelled");assert_eq!(state.processed,native["processed"].as_bool().unwrap(),"{label} processed");assert_eq!(state.random_state as u64,native["randomState"].as_u64().unwrap(),"{label} random");
    compare_settings(&state.settings,native["settingsBits"].as_str().unwrap(),native["committedPaletteArgbBits"].as_str().unwrap());let encoded=state.to_json();for(key,value)in native["stageKeys"].as_object().unwrap(){compare_json(&encoded["stageKeys"][key],value,&format!("{label} {key}"));}assert_eq!(state.stage_keys.palette,native["cacheKey"].as_str().unwrap());compare_json(&json!(state.completed),&native["completed"],"completed candidates");assert_eq!(bits(&state.scores),hex(native["scoreBits"].as_str().unwrap()),"{label} scores");for count in 0..25{assert_eq!(bits(&state.palettes[count]),hex(native["paletteBits"][count].as_str().unwrap()),"{label} palette {count}");}
    for(kind,image)in [("source",&state.source),("working",&state.working)]{compare_json(&json!([image.width,image.height]),&native[format!("{kind}Dimensions")],&format!("{label} {kind} dimensions"));assert_eq!(image.bgra,crate::common::b64(native[format!("{kind}Bgra")].as_str().unwrap()),"{label} {kind} pixels");}
    let map=state.segmentation.as_ref().unwrap();let expected=&native["segmentation"];compare_json(&json!([map.width,map.height]),&json!([expected["width"],expected["height"]]),"map dimensions");if expected["indicesInitialized"].as_bool().unwrap(){let actual:Vec<u8>=map.indices.as_ref().unwrap().iter().flat_map(|v|v.to_le_bytes()).collect();assert_eq!(actual,hex(expected["indexBits"].as_str().unwrap()),"{label} labels");}else{assert!(map.indices.is_none(),"{label} unavailable labels");}assert_eq!(bits(&map.palette),hex(expected["paletteBits"].as_str().unwrap()),"{label} live palette");compare_json(&json!(map.counts),&expected["counts"],"region counts");compare_json(&json!(map.color_indices),&expected["colorIndices"],"region colors");
    let shared=[state.parameters["usePalette"].as_bool().unwrap() as u32,state.parameters["Shared::is_anti_aliased"].as_f64().unwrap() as u32,0,state.parameters["shadowing"].as_bool().unwrap() as u32,state.parameters["clusterColors"].as_bool().unwrap() as u32,state.parameters["Shared::image_type_code"].as_f64().unwrap() as u32];assert_eq!(shared.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>(),hex(native["sharedBits"].as_str().unwrap()),"{label} shared controls");
    for(name,descriptor)in registry.as_object().unwrap(){let value=&state.parameters[name];let values=if let Some(a)=value.as_array(){a.iter().collect::<Vec<_>>()}else{vec![value]};assert_eq!(values.len(),descriptor["count"].as_u64().unwrap() as usize);let mut bytes=Vec::new();for value in values{let v=value.as_f64().unwrap();match descriptor["kind"].as_str().unwrap(){"float64"=>bytes.extend_from_slice(&v.to_le_bytes()),"float32"=>bytes.extend_from_slice(&(v as f32).to_le_bytes()),_=>bytes.extend_from_slice(&(v as i32).to_le_bytes())}}assert_eq!(bytes,hex(native["parameterBits"][name].as_str().unwrap()),"{label} {name}");}
    if !native["contours"].is_null(){compare_json(&encoded["contours"],&native["contours"],"live contours");let smoothing=state.smoothing.as_ref().unwrap();let expected=&native["smoothingMetadata"];compare_json(&json!(smoothing.border_counts),&expected["borderCounts"],"border counts");compare_json(&json!(smoothing.penalty_counts),&expected["penaltyCounts"],"penalty counts");let expected:Vec<f32>=expected["referencePositions"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap() as f32).collect();assert_eq!(bits(&smoothing.reference_positions),bits(&expected),"{label} references");}
    if !native["fittedGeometry"].is_null(){let mut geometry=native["fittedGeometry"].clone();let availability=geometry.as_object_mut().unwrap().remove("cubicAvailability").unwrap();let fitting=state.fitting.as_ref().unwrap();compare_json(&encoded["fitting"]["geometry"],&geometry,"fitted geometry");compare_json(&json!(fitting.cubic_availability),&availability,"cubic availability");assert_eq!(fitting.complete,fitting_complete,"{label} fitting complete");}
}
pub fn run_corpus(name:&str,expected_cases:usize,expected_cancellations:usize){
    let registry=registry();
    for task in [false,true]{let(mut cases,mut cancellations)=(0,0);
        for fixture in rows(&format!("{name}-reference.ndjson.gz")){
            if fixture["type"]=="metadata"{assert_eq!(fixture["wholeNativeResponsesRepeatIdentical"],true);continue;}
            let input=&fixture["input"];let native=&fixture["native"];let mut document=openvector::palette::CoreSession::default().create_document();document.set_source(input["width"].as_u64().unwrap() as usize,input["height"].as_u64().unwrap() as usize,&crate::common::b64(input["bgra"].as_str().unwrap()),true,0.0).unwrap();let mut previous_percent=0;
            for(index,selected)in input["steps"].as_array().unwrap().iter().enumerate(){
                let expected=&native["steps"][index];let mut controls=selected.clone();let palette:Vec<Value>=selected["palette"].as_array().unwrap().iter().flat_map(|v|v.as_array().map_or_else(||vec![v.clone()],Clone::clone)).collect();controls["palette"]=json!(palette);
                let action=selected["action"].as_u64().unwrap() as usize;let stage=["","segmentation","smoothing","fitting","palette","palette","palette","segmentation","smoothing","fitting"][action];let label=format!("{} step {index} {}",fixture["id"].as_str().unwrap(),if task{"task"}else{"direct"});let cancel_at=selected["cancelAt"].as_u64().unwrap() as usize;let mut events=Vec::new();let handle=document.cancellation_handle();let before=document.snapshot();
                let mut observer=|event:&DocumentProgress,state:&DocumentSnapshot|->Result<(),String>{
                    if fixture["mode"]==1&&event.percent==previous_percent{return Ok(());}previous_percent=event.percent;
                    let fraction_bits=event.fraction.to_le_bytes().iter().map(|v|format!("{v:02x}")).collect::<String>();events.push(if stage=="palette"{json!({"phase":1,"substep":event.color_count.unwrap(),"counter":event.iteration.unwrap()*5,"fractionBits":fraction_bits})}else{json!({"phase":event.phase,"substep":event.substep,"counter":event.counter,"fractionBits":fraction_bits})});
                    if events.len()==cancel_at{handle.store(true,Ordering::Relaxed);let mut live=state.clone();live.cancelled=true;compare_vector_document(&live,&expected["exceptions"][0]["state"],&registry,&format!("{label} first chance"),false,false);}Ok(())
                };
                let mut state=if action==5||action>=7{let result=document.run_task(stage,&controls,Some(&mut observer)).unwrap();assert!(!result.did_work,"{label} cached request");assert_eq!(expected["status"],0);if action==5{assert_eq!(result.state.status,before.status);}else{assert!(before.fitting.as_ref().unwrap().complete);compare_json(&result.state.to_json(),&before.to_json(),"cached owner state");}result.state}
                else if action==6&&expected["caught"].as_bool()==Some(true){let result=if task{document.run_task("palette",&controls,Some(&mut observer)).map(|r|r.state)}else{document.analyze(&controls,Some(&mut observer))};assert_eq!(result.unwrap_err(),CANCEL_TASK);assert_eq!(expected["status"],u32::MAX);let state=document.snapshot();assert_eq!(state.status,before.status);state}
                else if stage=="palette"{if action==6&&task{document.run_task("palette",&controls,Some(&mut observer)).unwrap().state}else{document.analyze(&controls,Some(&mut observer)).unwrap()}}
                else if task{document.run_task(stage,&controls,Some(&mut observer)).unwrap().state}else{match stage{"segmentation"=>document.segment(&controls,Some(&mut observer)).unwrap(),"smoothing"=>document.smooth(&controls,Some(&mut observer)).unwrap(),"fitting"=>document.fit(&controls,Some(&mut observer)).unwrap(),_=>unreachable!()}};
                let expected_events:Vec<Value>=expected["events"].as_array().unwrap().iter().map(|e|json!({"phase":e["header"][3],"substep":e["header"][4].as_u64().map_or_else(||e["header"][4].as_i64().unwrap() as i32,|v|v as u32 as i32),"counter":e["header"][5].as_u64().map_or_else(||e["header"][5].as_i64().unwrap() as i32,|v|v as u32 as i32),"fractionBits":e["fractionBits"]})).collect();compare_json(&json!(events),&json!(expected_events),&format!("{label} progress"));
                if cancel_at!=0{cancellations+=1;if stage!="palette"{if stage=="fitting"{assert!(!state.fitting.as_ref().unwrap().complete);}else if stage=="smoothing"{assert!(state.fitting.is_none());}else{assert!(state.stage_keys.segmentation.is_empty());}assert!(document.run_export(|_|panic!("incomplete fit reached writer")).is_err());}}
                if stage=="palette"{if let Some(f)=&state.fitting{compare_json(&json!([f.geometry.regions.len(),f.geometry.nodes.len(),f.geometry.cubic_storage_slots]),&expected["state"]["geometryContainerCounts"],"retained geometry containers");}}
                let returned=action!=5&&action<7&&!(action==6&&expected["caught"].as_bool()==Some(true));let complete=action==9||(returned&&expected["state"]["status"]==0);compare_vector_document(&state,&expected["state"],&registry,&label,returned,complete);
                if let Some(f)=state.fitting.as_mut(){f.geometry.nodes[0].x=f64::NAN;f.cubic_availability.fill(99);if let Some(c)=f.geometry.cubics.first_mut(){c.points.fill(f64::NAN);}}if action==2{state.contours.as_mut().unwrap().nodes[0].x=f64::NAN;}
            }cases+=1;
        }assert_eq!((cases,cancellations),(expected_cases,expected_cancellations),"{name} corpus cardinality");
    }
}
